local function C_8()
local script = G2L["8"];
	local lplr = game.Players.LocalPlayer

	while true do
		lplr.Character.Humanoid.WalkSpeed = script.Parent.Text
		task.wait(0.0001)
	end
end;
task.spawn(C_8);
-- StarterGui.HumacharUI.Topbar.MainFrameHC.JumpEnter.LocalScript
local function C_c()
local script = G2L["c"];
	local lplr = game.Players.LocalPlayer
	game.StarterPlayer.CharacterUseJumpPower = true

	lplr.CharacterAdded:Connect(function(char)
		char:WaitForChild("Humanoid").UseJumpPower = true
	end)

	if lplr.Character then
		lplr.Character.Humanoid.UseJumpPower = true
	end

	while true do
		lplr.Character.Humanoid.JumpPower = tonumber(script.Parent.Text) or 50
		task.wait(0.0001)
	end
end;
task.spawn(C_c);
